// builders/ — model builders: canonical atom → pure model object (no strings).
// Mirrors the internal Builder→Model→Template triad; templates render, builders decide.
// inc3 (2026-10-12): reference rebased from the stale golden_master snapshot to LIVE
// CodegenMain output (fresh run). Three systematic drifts absorbed here:
//   ① header lines `@generated by CodegenMain:<v>` + `@knowledge-release <kr>`
//      (v = generator-side fact → generate option; kr = knowledge-side fact → canonical slot;
//       both mirror internal semantics: v never participates in comparisons, kr omitted when absent)
//   ② framework base `net.imadz.framework.common.*` → `net.imadz.common.*` (canonical.framework.base)
//   ③ command/event refs self-qualified (`<Proto>.<Command>`, events under the entity path)
// All import lists are decided HERE (sorted; deliberate duplicates preserved as artifacts —
// e.g. duplicated Future/runReplyingPolicy/EventHandler imports come from internal Set-of-TypeRef
// semantics where equal fqns with different type params both survive).
import { kebab, scalaType } from './naming.mjs';

const baseOf = (a) => `${a.pkg ?? 'net.imadz'}.${a.ctxPackage ?? ''}.`;
const protoFqn = (a) => `${baseOf(a)}application.aggregates.${a.name}Protocol`;
const entityName = (a) => a.entity ?? `${a.name}Entity`;
const entityFqn = (a) => `${baseOf(a)}domain.entities.${entityName(a)}`;
const aggFqn = (a) => `${baseOf(a)}application.aggregates.${a.name}Aggregate`;

export function headerOf(env) {
  const kr = env.knowledgeRelease ? `// @knowledge-release ${env.knowledgeRelease}\n` : '';
  return `// @generated by CodegenMain:${env.generatorVersion}\n${kr}`;
}

const replyNameOf = (a, c) =>
  !c.reply || c.reply === 'aggregate'
    ? (a.aggregateReply?.name ?? `${c.name}Confirmation`)
    : (typeof c.reply === 'string' ? c.reply : (c.reply?.name ?? `${c.name}Confirmation`));

// unique reply names in first-appearance order (drives both body and self-qualified imports)
function replyNames(a) {
  const seen = new Set(), out = [];
  for (const c of a.commands ?? []) {
    const rn = replyNameOf(a, c);
    if (!seen.has(rn)) { seen.add(rn); out.push(rn); }
  }
  return out;
}

export function protocolModel(a, env) {
  const name = a.name;
  const commands = (a.commands ?? []).map((c) => ({
    name: c.name,
    params: [...(c.parameters ?? []).map((p) => ({ name: p.name, type: scalaType(p.dataType) })),
      { name: 'replyTo', type: `ActorRef[${replyNameOf(a, c)}]` }],
  }));
  const replies = replyNames(a).map((rn) => {
    const c = (a.commands ?? []).find((x) => replyNameOf(a, x) === rn);
    return { name: rn, fields: (!c.reply || c.reply === 'aggregate' ? a.aggregateReply?.fields : c.reply?.fields) ?? [{ name: 'error', type: 'Option[iMadzError]' }] };
  });
  const paramImports = [];
  for (const c of a.commands ?? []) for (const p of c.parameters ?? [])
    if (p.typeImport && !paramImports.includes(p.typeImport)) paramImports.push(p.typeImport);
  const fb = env.frameworkBase;
  const usesId = commands.some((c) => c.params.some((p) => p.type.includes('Id'))) || replies.some((r) => r.fields.some((f) => f.type.includes('Id')));
  const usesError = replies.some((r) => r.fields.some((f) => f.type.includes('iMadzError')));
  const usesList = replies.some((r) => r.fields.some((f) => f.type.startsWith('List[')));
  const imports = [
    'akka.actor.typed.ActorRef',
    ...replyNames(a).map((rn) => `${protoFqn(a)}.${rn}`),
    `${protoFqn(a)}.${name}Command`,
    `${entityFqn(a)}.${name}Event`,
    `${entityFqn(a)}.${name}State`,
    ...paramImports,
    `${fb}.CborSerializable`,
    ...(usesId ? [`${fb}.CommonTypes.Id`] : []),
    ...(usesError ? [`${fb}.CommonTypes.iMadzError`] : []),
    ...(usesList ? ['scala.collection.immutable.List'] : []),
  ].sort();
  return { header: headerOf(env), base: baseOf(a), name, imports, commands, replies };
}

export function rootModel(a, env) {
  const name = a.name;
  const imports = [
    'akka.cluster.sharding.typed.scaladsl.EntityTypeKey',
    'akka.persistence.typed.scaladsl.Effect',
    `${protoFqn(a)}.${name}Command`,
    `${baseOf(a)}application.aggregates.behaviors.${name}Behaviors`,
    `${entityFqn(a)}.${name}Event`,
    `${entityFqn(a)}.${name}State`,
  ].sort();
  return {
    header: headerOf(env), base: baseOf(a), name, imports,
    commandHandlerFqn: `${protoFqn(a)}.${name}CommandHandler`,
    typeKey: a.persistence?.typeKey ?? a.name,
    tagCount: a.persistence?.tagCount ?? 5,
    tagPrefix: kebab(name),
  };
}

export function entityModel(a, env) {
  const name = a.name;
  const voImports = [];                                  // first-appearance VO type imports (state fields + payloads)
  const see = (t) => { if (t && !voImports.includes(t)) voImports.push(t); };
  const fields = (a.stateFields ?? []).map((f) => {
    see(f.typeImport);
    return { name: f.name, type: scalaType(f.dataType), defaultValue: f.defaultValue };
  });
  const events = (a.events ?? []).map((e) => {
    for (const p of e.payloads ?? []) if (p.typeImport) see(p.typeImport);
    return { name: e.name, params: (e.payloads ?? []).map((p) => ({ name: p.name, type: scalaType(p.dataType) })) };
  });
  const idType = scalaType(a.identifierType ?? 'string (uuid)');
  const usesMap = fields.some((f) => f.type.startsWith('Map['));
  const hasDefaults = fields.some((f) => f.defaultValue);
  const usesId = idType === 'Id' || fields.some((f) => f.type.includes('Id'));
  const fb = env.frameworkBase;
  // duplicated Map import = internal artifact (collectionImports + defaults deps both carry it)
  const imports = [
    ...voImports,
    `${fb}.CborSerializable`,
    ...(usesId ? [`${fb}.CommonTypes.Id`] : []),
    ...(usesMap ? ['scala.collection.immutable.Map'] : []),
    ...(usesMap && hasDefaults ? ['scala.collection.immutable.Map'] : []),
  ].sort();
  const identifier = (a.stateFields ?? []).find((f) => f.name === a.identifier)?.name ?? a.identifier;
  return { header: headerOf(env), base: baseOf(a), name, imports, fields, events, idType, identifier };
}

// Ruling A (2026-10-12): fold exprs beyond the state./param./literal: vocabulary are
// emitted verbatim as Scala expressions (fail-open — the generator never decides
// business semantics); cross-field helper calls get an AI_PROMPT stub synthesized
// from the aggregate's declared stateHelpers.
export function eventHandlerModel(a, env) {
  const name = a.name;
  const javaImports = [], valueImports = new Set();
  for (const h of a.stateHelpers ?? [])
    for (const p of h.params ?? []) {
      if (!p.typeImport) continue;
      if (p.typeImport.startsWith('java.')) { if (!javaImports.includes(p.typeImport)) javaImports.push(p.typeImport); }
      else valueImports.add(p.typeImport);
    }
  // inc3: event family + state + handler live under the ENTITY path (live semantics);
  // every event name is imported individually (they are referenced bare in the match cases)
  const entityQualified = [
    `${name}Event`, `${name}EventHandler`, `${name}EventHandler`, `${name}State`,   // handler ×2 = internal artifact
    ...(a.events ?? []).map((e) => e.name),
  ].map((n) => `${entityFqn(a)}.${n}`);
  const values = [...valueImports].map((t) => (t.includes('.') ? t : `${baseOf(a)}domain.values.${t}`));
  const usesMap = (a.stateHelpers ?? []).some((h) => (h.returnType ?? '').startsWith('Map['));
  const imports = [...javaImports, ...entityQualified, ...values, ...(usesMap ? ['scala.collection.immutable.Map'] : [])].sort();
  const events = (a.events ?? [])
    .filter((e) => (e.foldAssignments ?? []).length)
    .map((e) => ({ name: e.name, folds: e.foldAssignments }));
  return { header: headerOf(env), base: baseOf(a), name, imports, events, helpers: a.stateHelpers ?? [] };
}

export function repositoryModel(a, env) {
  const name = a.name;
  const fb = env.frameworkBase;
  const imports = [
    'akka.cluster.sharding.typed.scaladsl.EntityRef',
    'akka.cluster.sharding.typed.scaladsl.EntityRef',      // ×2 = internal artifact
    'com.google.inject.ImplementedBy',
    'com.google.inject.ImplementedBy',                     // ×2 = internal artifact
    'javax.inject.Inject',
    'javax.inject._',
    aggFqn(a),
    `${aggFqn(a)}._`,
    `${baseOf(a)}application.aggregates.${name}AggregateProtocol.${name}AggregateCommandFamily`,
    `${protoFqn(a)}.${name}Command`,
    `${baseOf(a)}infrastructure.repositories.aggregate.${name}RepositoryImpl`,
    `${fb}.CommonTypes.Id`,
  ].sort();
  return {
    header: headerOf(env), base: baseOf(a), name, imports,
    implName: `${name}RepositoryImpl`,
    entityRefMethod: `  def entityRef(id: String): EntityRef[${name}AggregateCommandFamily]
  // Logic: sharding 实体引用（聚合隐式契约——对齐 gen_api_layer entityRef，2026-08-28 终局原则）`,
    finders: (a.repository?.finders ?? []).map((f) => ({
      name: f.name,
      param: `${f.param.name}: ${scalaType(f.param.dataType)}`,
      logic: f.logic ?? '通过 Sharding 获取聚合根引用',
    })),
  };
}

// Factory semantics (internal AggregateFactoryBuilder, live):
//   ref method  = create<Base>WithoutBalance (template literal — "Balance" is not data-driven)
//   init method = first non-readOnly command with params; method NAME from the first
//                 factoryMethods entry that has params (CreditBalance: same name → overload),
//                 fallback create<Base>WithInitialValue
//   hasIdParam  = init command carries a param named like the aggregate identifier
//                 (ask then passes it; otherwise the id param only locates the entity)
export function factoryModel(a, env) {
  const name = a.name;
  const aggBase = name.replace(/Aggregate$/, '');
  const fb = env.frameworkBase;
  const identifier = a.identifier ?? 'id';
  const initCmd = (a.commands ?? []).find((c) => (c.parameters ?? []).length > 0 && !c.readOnly);
  if (!initCmd) throw new Error(`aggregate ${name}: no non-readOnly command with parameters — cannot build factory init method`);
  const initName = (a.factoryMethods ?? []).find((m) => (m.params ?? []).length > 0)?.name ?? `create${aggBase}WithInitialValue`;

  const idParam = { name: identifier, type: 'Id', import: `${fb}.CommonTypes.Id` };
  const business = (initCmd.parameters ?? [])
    .filter((p) => p.name !== 'replyTo')
    .map((p) => ({ name: p.name, type: scalaType(p.dataType), import: p.typeImport ?? null }));
  const hasIdParam = business.some((p) => p.name === identifier);
  const methodParams = hasIdParam ? business : [idParam, ...business];
  const askArgs = [...(hasIdParam ? methodParams : business).map((p) => p.name), '_'].join(', ');
  const reply = replyNameOf(a, initCmd);

  const refMethod = {
    name: `create${aggBase}WithoutBalance`,
    params: [idParam],
    ret: `EntityRef[${name}Command]`,
    body: `    clusterSharding.entityRefFor(${name}Aggregate.entityTypeKey, ${identifier}.toString)`,
  };
  const initMethod = {
    name: initName,
    params: methodParams,
    ret: `Future[Either[iMadzError, EntityRef[${name}Command]]]`,
    body: [
      `    val entityRef: EntityRef[${name}Command] = clusterSharding`,
      `      .entityRefFor[${name}Command](${name}Aggregate.entityTypeKey, ${identifier}.toString)`,
      `    for {`,
      `      confirmation <- entityRef.ask[${reply}](${initCmd.name}(${askArgs}))`,
      `    } yield {`,
      `      confirmation.error`,
      `        .map(Left.apply[iMadzError, EntityRef[${name}Command]])`,
      `        .getOrElse(Right(entityRef))`,
      `    }`,
    ].join('\n'),
  };

  const protoQualified = (a.commands ?? []).map((c) => `${protoFqn(a)}.${c.name}`);
  for (const rn of replyNames(a)) protoQualified.push(`${protoFqn(a)}.${rn}`);
  protoQualified.push(`${protoFqn(a)}.${name}Command`);
  const paramImports = [];
  for (const p of methodParams) if (p.import && p.import !== idParam.import && !paramImports.includes(p.import)) paramImports.push(p.import);
  const imports = [
    'akka.cluster.sharding.typed.scaladsl.ClusterSharding',
    'akka.cluster.sharding.typed.scaladsl.EntityRef',
    'akka.util.Timeout',
    'javax.inject.Inject',
    aggFqn(a),
    ...protoQualified,
    ...paramImports,
    `${fb}.CommonTypes.Id`,
    `${fb}.CommonTypes.iMadzError`,
    'scala.concurrent.ExecutionContext',
    'scala.concurrent.Future',
    'scala.concurrent.Future',                             // ×2 = internal artifact (returnType deps + known types)
    'scala.concurrent.duration._',
  ].sort();
  return { header: headerOf(env), base: baseOf(a), name, imports, refMethod, initMethod };
}

// Behaviors semantics (internal AggregateBehaviorBuilder, live):
//   groups from canonical behaviors (flows → runReplyingPolicy(<Rule>Rule, <Cmd>Helper))
//   read-only commands fall into the trailing queryBehaviors group (AI_PROMPT + Effect.reply)
//   apply chain = groups in order + queryBehaviors, wrapped in a MANUAL block
export function behaviorsModel(a, env) {
  const name = a.name;
  const fb = env.frameworkBase;
  const commands = a.commands ?? [];
  const readOnly = commands.filter((c) => c.readOnly);
  const groups = (a.behaviors ?? []).map((g) => ({
    method: g.name.charAt(0).toLowerCase() + g.name.slice(1),
    handlers: (g.flows ?? []).map((f) => ({ command: f.command, ruleType: `${f.rule}Rule`, helper: `${f.command}Helper` })),
  }));
  const queryHandlers = readOnly.map((c) => ({ command: c.name, replyType: replyNameOf(a, c) }));
  const methods = [...groups.map((g) => g.method), ...(queryHandlers.length ? ['queryBehaviors'] : [])];
  const chain = `${methods[0]}(state)` + methods.slice(1).map((mth) => `.orElse(${mth}(state))`).join('') + '.apply(command)';

  const protoQualified = [`${protoFqn(a)}.${name}Command`, ...commands.map((c) => `${protoFqn(a)}.${c.name}`)];
  for (const c of readOnly) protoQualified.push(`${protoFqn(a)}.${replyNameOf(a, c)}`);
  const ruleImports = [];
  for (const g of a.behaviors ?? []) for (const f of g.flows ?? []) ruleImports.push(`${baseOf(a)}domain.invariant.${f.rule}Rule`);
  const imports = [
    'akka.persistence.typed.scaladsl.Effect',
    protoFqn(a),
    ...protoQualified,
    `${protoFqn(a)}._`,
    entityFqn(a),
    `${entityFqn(a)}.${name}Event`,
    `${entityFqn(a)}.${name}State`,
    ...ruleImports,
    `${fb}.application.CommandHandlerReplyingBehavior.runReplyingPolicy`,
    `${fb}.application.CommandHandlerReplyingBehavior.runReplyingPolicy`,   // ×2 = internal artifact
    'scala.concurrent.duration._',
  ].sort();
  return { header: headerOf(env), base: baseOf(a), name, imports, groups, queryHandlers, chain };
}

// CommandHelpers semantics (internal CommandHelpersBuilder, live — 2026-09-21 欠账⑦ skeleton):
//   param = single param type | tuple | Unit; toParam = command.x | (xs) | ()
//   reply = flow successReply (write) | replyToType (read-only); Unit reply → () construction
//   tuple param → Reply(param._1, None|Some(error)); else Reply(param, None|Some(error))
//   three bodies inside MANUAL blocks with a compilable mechanical skeleton (not bare ???)
export function helpersModel(a, env) {
  const name = a.name;
  const fb = env.frameworkBase;
  const commands = a.commands ?? [];
  const flows = new Map();
  for (const g of a.behaviors ?? []) for (const f of g.flows ?? []) flows.set(f.command, f);
  const helpers = commands.map((c) => {
    const params = (c.parameters ?? []).filter((p) => p.name !== 'replyTo');
    let paramSig, toParam;
    if (params.length === 1) { paramSig = scalaType(params[0].dataType); toParam = `command.${params[0].name}`; }
    else if (params.length > 1) {
      paramSig = `(${params.map((p) => scalaType(p.dataType)).join(', ')})`;
      toParam = `(${params.map((p) => `command.${p.name}`).join(', ')})`;
    } else { paramSig = 'Unit'; toParam = '()'; }
    const reply = (c.readOnly ? undefined : flows.get(c.name)?.successReply) ?? replyNameOf(a, c);
    const unit = reply === 'Unit';
    const tuple = params.length > 1;
    return {
      name: `${c.name}Helper`, command: c.name, paramSig, toParam, reply,
      success: unit ? '()' : tuple ? `${reply}(param._1, None)` : `${reply}(param, None)`,
      failure: unit ? '()' : tuple ? `${reply}(param._1, Some(error))` : `${reply}(param, Some(error))`,
    };
  });
  const protoQualified = commands.map((c) => `${protoFqn(a)}.${c.name}`);
  for (const rn of replyNames(a)) protoQualified.push(`${protoFqn(a)}.${rn}`);
  const paramImports = [];
  for (const c of commands) for (const p of c.parameters ?? [])
    if (p.typeImport && !paramImports.includes(p.typeImport)) paramImports.push(p.typeImport);
  const imports = [
    ...protoQualified,
    `${entityFqn(a)}.${name}State`,
    ...paramImports,
    `${fb}.CommonTypes.Id`,
    `${fb}.CommonTypes.iMadzError`,
    `${fb}.application.CommandHandlerReplyingBehavior.CommandHelper`,
  ].sort();
  return { header: headerOf(env), base: baseOf(a), name, imports, helpers, state: `${name}State` };
}
